export class RequestError extends Error {
  readonly status:number;
  readonly code:string;
  readonly payload:z.infer<typeof errorResponseSchema>;
  constructor(status:number,payload:z.infer<typeof errorResponseSchema>){super(payload.error);this.name='RequestError';this.status=status;this.code=payload.code??`HTTP_${status}`;this.payload=payload;}
}
async function requestJSON(path:string, body?:unknown):Promise<unknown> {
  const response=await fetch(path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});
  let data:unknown;
  try{data=await response.json();}catch{if(!response.ok)throw new RequestError(response.status,{error:'The request could not be completed.'});throw new Error('The server response was not valid JSON.');}
  if(!response.ok) { const err=errorResponseSchema.safeParse(data); throw new RequestError(response.status,err.success?err.data:{error:'The request could not be completed.'}); }
  return data;
}
export type DashboardSensitiveStateScrub=Readonly<{
  invalidateGeneration:()=>void;
  retireAutosave:()=>void;
  clearWorkspacePlaintext:()=>void;
  clearGitHubToken:()=>void;
  clearSyncSecrets:()=>void;
  clearAuthenticationState:()=>void;
  hideWorkspace:()=>void;
}>;
export function scrubDashboardSensitiveState(actions:DashboardSensitiveStateScrub):void {
  actions.invalidateGeneration();
  actions.retireAutosave();
  actions.clearWorkspacePlaintext();
  actions.clearGitHubToken();
  actions.clearSyncSecrets();
  actions.clearAuthenticationState();
  actions.hideWorkspace();
}
export async function runAuthenticatedDashboardRequest<T>(request:()=>Promise<T>,onAuthenticationLoss:(reason:RequestError)=>void):Promise<T>{
  try{return await request();}catch(reason){if(reason instanceof RequestError&&reason.status===401)onAuthenticationLoss(reason);throw reason;}
}
function replaceFile(files:Workspace['files'],file:Workspace['files'][number]):Workspace['files']{
  const found=files.some(candidate=>candidate.path===file.path);
  return found?files.map(candidate=>candidate.path===file.path?file:candidate):[...files,file].sort((left,right)=>left.path.localeCompare(right.path));
}
function autosaveFailure(error:unknown):AutosaveFailure{
  if(error instanceof RequestError){
    if(error.code==='VERSION_CONFLICT')return new AutosaveFailure('conflict',error.message,error.payload.file??null);
    if(error.code==='FILE_NOT_FOUND')return new AutosaveFailure('conflict',error.message,null);
    if(error.status>=400&&error.status<500)return new AutosaveFailure('invalid',error.message);
    return new AutosaveFailure('transient',error.message);
  }
  if(error instanceof TypeError||error instanceof SyntaxError||error instanceof z.ZodError)return new AutosaveFailure(navigator.onLine?'uncertain':'offline',navigator.onLine?'The save response was lost; checking the server before retrying.':'You are offline. The encrypted draft will retry when you reconnect.');
  return new AutosaveFailure('unknown',error instanceof Error?error.message:'Autosave failed.');
}
function download(name:string, value:unknown) { const blob=new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type:typeof value==='string'?'text/plain':'application/json'}); const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000); }
async function copy(text:string) { try {await navigator.clipboard.writeText(text);toast.success('Copied to clipboard');}catch{download('local-sandbox.txt',text);toast('Downloaded the text. Clipboard access is unavailable.');} }
const providerNames={local:'Locally',apple:'Apple Intelligence',chatgpt:'ChatGPT',grok:'Grok',grokbot:'Grokbot',claude:'Claude'};
function providerLabel(provider:string|null|undefined):string {
  switch(provider){case 'local':return 'Locally';case 'apple':return 'Apple Intelligence';case 'chatgpt':return 'ChatGPT';case 'grok':return 'Grok';case 'grokbot':return 'Grokbot';case 'claude':return 'Claude';case 'system':return 'Local Sandbox';default:return 'Provider not recorded';}
}
function handoffOriginLabel(origin:ProviderHandoffEvent['origin']):string{return origin==='app-intent'?'Siri or App Shortcut':'Local Sandbox app';}
function providerSelectionLabel(selection:ProviderHandoffEvent['selection']):string {
  switch(selection){case 'saved':return 'Saved provider';case 'best-local':return 'Best local';default:return providerLabel(selection);}
}
function providerAccessEvidenceLabel(evidence:ProviderRoutingEvidence['accessEvidence']):string {
  switch(evidence){
    case'on-device-runtime':return'on-device runtime';
    case'recent-locally-validated-response':return'recent locally validated response';
    case'configured-unmeasured':return'configured, unmeasured';
    case'unavailable':return'unavailable';
  }
}
function receiptOriginLabel(receipt:Receipt):string {
  const handoff=providerHandoffTimeline(receipt);
  if(handoff.kind==='valid'&&handoff.events[0])return handoffOriginLabel(handoff.events[0].origin);
  if(receipt.taskOrigin)return handoffOriginLabel(receipt.taskOrigin);
  switch(receipt.origin){case 'native':return 'Native on-device runner';case 'shortcut':return 'App Shortcut';case 'cloud-sandbox':return 'Hosted sandbox';}
}
function requireWorkspaceCommit<T>(scope:WorkspaceSessionScope,commit:()=>T):T{return requireCurrentWorkspaceResult(scope.commit(commit));}
class AutosaveSlot {
  private current:AutosaveCoordinator|null=null;
  private readonly listeners=new Set<()=>void>();
  readonly subscribe=(listener:()=>void)=>{this.listeners.add(listener);return()=>this.listeners.delete(listener);};
  readonly getSnapshot=()=>this.current;
  replace(next:AutosaveCoordinator|null){if(this.current===next)return;const prior=this.current;this.current=next;prior?.dispose();for(const listener of this.listeners)listener();}
  clear(expected:AutosaveCoordinator){if(this.current===expected)this.replace(null);}
}

