  async function createEncryptedSync(){await act('sync-create',async()=>{if(syncPassphrase!==syncConfirm)throw Error('The recovery passphrases do not match.');const scope=workspaceSessionGeneration.bind();const created=await EncryptedWorkspaceSyncClient.create(syncPassphrase,syncRepository,syncWriter.current);requireWorkspaceCommit(scope,()=>{setSyncClient(created.client);setSyncSelected(created.client.workspaceId);setSyncPassphrase('');setSyncConfirm('');setSyncRemote([]);setSyncConflict(null);});await loadSyncWorkspaces(scope);toast.success('Encrypted workspace enrolled. Keep the recovery passphrase somewhere safe.');});}
  async function unlockEncryptedSync(){await act('sync-unlock',async()=>{if(!syncSelected)throw Error('Choose an encrypted workspace first.');const scope=workspaceSessionGeneration.bind();const selected=syncSelected;const passphrase=syncPassphrase;const snapshot=await syncRepository.readWorkspace(selected);requireWorkspaceCommit(scope,()=>undefined);const client=await EncryptedWorkspaceSyncClient.restore(snapshot.recovery,passphrase,syncRepository,syncWriter.current);requireWorkspaceCommit(scope,()=>undefined);const remote=await client.pull();requireWorkspaceCommit(scope,()=>{setSyncClient(client);setSyncPassphrase('');setSyncConfirm('');setSyncConflict(null);setSyncRemote(remote);});toast.success('Encrypted workspace unlocked for this tab');});}
