      const pulled=await client.pull();requireWorkspaceCommit(scope,()=>undefined);
      const verified=pulled.find(item=>item.value.path===value.path&&item.record.revision===result.record.revision&&item.value.content===null);
      if(!verified)throw Error('The deletion tombstone did not authenticate on readback.');
      requireWorkspaceCommit(scope,()=>{setSyncConflict(null);setSyncRemote(pulled);});
