  async function deleteAppleAccountFromDashboard(){
    const activeSession=appleSession;
    let pendingScope:string|null;let pendingWorkspaceScope:string|null;
    try{pendingScope=appleAccountDeletion.pendingAccountScope();pendingWorkspaceScope=appleAccountDeletion.pendingWorkspaceScope();}
    catch(reason){const message=reason instanceof Error?reason.message:'Account deletion retry storage is unavailable.';setAppleSessionError(message);toast.error(message);return;}
    if(activeSession&&pendingScope!==null&&pendingScope!==activeSession.deletionScope){setAppleSessionError('The saved deletion request belongs to a different Apple identity. Disconnect this Apple session before checking it.');return;}
    const accountScope=activeSession?.deletionScope??pendingScope;
    const accountMode=activeSession?appleMode:appleAccountDeletionMode;
    const workspaceScope=activeSession?workspaceRef.current.workspaceId:pendingWorkspaceScope;
    if(accountScope===null||accountMode===null||workspaceScope===null||!/^[A-Za-z0-9_-]{32}$/.test(workspaceScope)){setAppleSessionError('The workspace bound to this deletion attempt is unavailable. Reload the account before retrying.');return;}
    await act('apple-delete',async()=>{
      try{
        const outcome=await appleAccountDeletion.deleteIfConfirmed({
          confirmed:true,
          accountScope,
          workspaceScope,
          accountMode,
          scrub:async response=>{const cleanup=scrubDeletedWorkspace(workspaceScope);try{appleAccountLifecycle.publishLock(workspaceScope);}catch(reason){void cleanup.catch(()=>undefined);throw reason;}await cleanup;appleAccountLifecycle.publish(response.providerCredentials.manualRevocationRequired,response.originConnections.manualRevocationRequired,accountMode,workspaceScope);},
        });
        if(outcome.kind==='cancelled')return;
        setAppleAccountDeletionFollowUp(appleAccountDeletion.pendingManualFollowUp());
        setAppleAccountDeleteConfirm(false);setAppleAccountDeletionScope(null);setAppleAccountDeletionMode(null);
        const completed=accountMode==='linked'?'Apple access removed; the ChatGPT-owned workspace was retained.':'Apple account and Local Sandbox server data deleted.';
        const followUp=[outcome.response.providerCredentials.manualRevocationRequired?'Remove Local Sandbox in Apple Account settings.':'',outcome.response.originConnections.manualRevocationRequired?'Remove any remaining Local Sandbox installation in Cursor Origin settings.':''].filter(Boolean).join(' ');
        toast.success(followUp?`${completed} ${followUp}`:completed);
      }catch(reason){
        try{setAppleAccountDeletionScope(appleAccountDeletion.pendingAccountScope());setAppleAccountDeletionMode(appleAccountDeletion.pendingAccountMode());}catch{setAppleAccountDeletionScope(accountScope);setAppleAccountDeletionMode(accountMode);}
        setAppleSessionError('Account deletion completion was not fully verified. The server may already have completed deletion, and this tab was locked before local cleanup. Retry with the same saved request key.');
        throw reason;
      }
    });
  }
